import sys
# Покомпонентные ограничения на 5 байт входа.
def check(s):
    if len(s) != 5: return False
    a, b, c, d, e = [ord(x) for x in s]
    return (a == 0x6e) and (b - 0x74 == 0) and (c == 0x6f) and (d == 0x7b) and (e + 0 == 0x7d)
if __name__ == '__main__':
    print("OK" if len(sys.argv) > 1 and check(sys.argv[1]) else "NO")
